"""Builds data.js and one page per product from tools/data.json.

Edit tools/data.json (links, WhatsApp, prices, products), then run:
    python3 tools/build.py
"""
import json, html, pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
data = json.loads((ROOT / "tools" / "data.json").read_text())

(ROOT / "data.js").write_text(
    "/* Generated by tools/build.py from tools/data.json. Edit that file, not this one. */\n"
    "window.SITE = " + json.dumps(data, ensure_ascii=False, indent=1) + ";\n"
)

e = html.escape
TEMPLATE = (ROOT / "tools" / "product.template.html").read_text()
out = ROOT / "products"
out.mkdir(exist_ok=True)
for old in out.glob("*.html"):
    old.unlink()

for p in data["PRODUCTS"]:
    features = "".join(f"<li>{e(f)}</li>" for f in p["features"])
    sheet = (f'<p><a class="sheet" href="{e(p["sheet"])}" target="_blank" rel="noopener">'
             f'Read the official NeoLife fact sheet (PDF) →</a></p>') if p.get("sheet") else ""
    sold = '<p class="soldout">Temporarily sold out</p>' if p.get("soldOut") else ""
    page = (TEMPLATE
            .replace("{{slug}}", e(p["slug"]))
            .replace("{{name}}", e(p["name"]))
            .replace("{{size}}", e(p["size"]))
            .replace("{{need}}", e(p["need"]))
            .replace("{{desc}}", e(p["desc"]))
            .replace("{{features}}", features)
            .replace("{{use}}", e(p["use"]))
            .replace("{{sheet}}", sheet)
            .replace("{{sold}}", sold))
    (out / f'{p["slug"]}.html').write_text(page)

print(f'Built data.js and {len(data["PRODUCTS"])} product pages.')
